def one_loop(n):
    steps = 0
    for i in range(n):
        steps += 1          # the loop body runs n times
    return steps

def nested_loops(n):
    steps = 0
    for i in range(n):
        for j in range(n):
            steps += 1      # runs n times for EACH i
    return steps

for n in [10, 100, 1000]:
    print(f"n = {n:5}:   one loop = {one_loop(n):7,}    nested = {nested_loops(n):11,}")

